import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0012: 为什么禁止未经授权的高风险网络动作","description":"","frontmatter":{},"headers":[],"relativePath":"zh/adr/ADR-0012-why-unauthorized-high-risk-network-actions-are-forbidden.md","filePath":"zh/adr/ADR-0012-why-unauthorized-high-risk-network-actions-are-forbidden.md","lastUpdated":0}`),a={name:`zh/adr/ADR-0012-why-unauthorized-high-risk-network-actions-are-forbidden.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0012-为什么禁止未经授权的高风险网络动作" tabindex="-1">ADR-0012: 为什么禁止未经授权的高风险网络动作 <a class="header-anchor" href="#adr-0012-为什么禁止未经授权的高风险网络动作" aria-label="Permalink to “ADR-0012: 为什么禁止未经授权的高风险网络动作”">​</a></h1><ul><li>状态：已接受</li><li>日期：2026-10-31</li><li>关联：docs/guide/security.md §12.2，platforms.md</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>自愈引擎拥有重启服务、重置网络接口、改路由的权限。网络类动作与普通服务重启 有本质区别：<strong>它可能切断管理通道</strong>——Wi-Fi 重连失败、默认路由被清、防火墙被重置， 引擎就会与操作者彻底失联，且此刻正是系统最需要人的时候。自愈系统把自己搞失联 是最坏的失败模式。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to “决策”">​</a></h2><p>高风险动作（<code>RiskLevel::High</code>：网络接口重置、系统重启、清防火墙等）默认拒绝， 必须显式授权（<code>permissions.default_allow_high_risk</code> 或每资源 <code>recovery_policy.allow_high_risk</code>）才可执行，且每次执行进授权审计； 接口重置类动作必须显式标记&quot;可能中断管理通道&quot;；网络操作全局互斥（P3）， 禁止默认清防火墙/重置全部路由这类不可逆操作。</p><h2 id="替代方案" tabindex="-1">替代方案 <a class="header-anchor" href="#替代方案" aria-label="Permalink to “替代方案”">​</a></h2><ul><li><strong>默认允许、事后审计</strong>：失联发生后审计毫无意义。</li><li><strong>按资源粒度默认允许</strong>：一次配置疏忽即全量暴露。</li></ul><h2 id="优缺点" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点" aria-label="Permalink to “优缺点”">​</a></h2><p>优点：破坏性动作的爆炸半径被配置显式控制；审计链可回答&quot;谁授权的、何时执行&quot;。 缺点：需要配置才有能力（文档与示例必须讲清楚）； &quot;值得开高风险&quot;的判断落在用户身上。</p><h2 id="后续影响" tabindex="-1">后续影响 <a class="header-anchor" href="#后续影响" aria-label="Permalink to “后续影响”">​</a></h2><ul><li>P2 平台适配器的每个危险原语都必须先有权限检查（todo P2 §权限检查）。</li><li>P4 授权界面与审计同源，不自建权限模型。</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};